"""Print one markdown row comparing a CI cell with the original macOS run.
CI outcome: number of KSP-generated files (Moshi adapters and the local processor's output) and
the state of :app:kspDebugKotlin. Usage: ksp_compare.py RESULT_TXT LOG_DIR (cell JSON in env C)."""
import glob, json, os, re, sys

c = json.loads(os.environ["C"])
res = open(sys.argv[1]).read() if os.path.exists(sys.argv[1]) else ""
log = "".join(open(p).read() for p in glob.glob(f"{sys.argv[2]}/{c['label']}.log"))
gen = log.split("## generated by KSP:")[-1] if "## generated by KSP:" in log else ""
moshi = len(re.findall(r"JsonAdapter\.kt$", gen, re.M))
total = len(re.findall(r"\.kt$", gen, re.M))
m = re.search(r":app:kspDebugKotlin (SKIPPED|UP-TO-DATE|NO-SOURCE|FAILED)", log)
task = m[1] if m else ("ran" if ":app:kspDebugKotlin" in log else "absent")
rc = re.search(r"rc=(\d+)", res)
ci = "generated" if moshi else "nothing generated"
mac = "generated" if c["mac_generated"] else "nothing generated"
same = "same" if (ci == mac and (task == "SKIPPED") == (c["mac_ksp_task"] == "SKIPPED")) else "**DIFFERENT**"
print(f"| {c['label']} | AGP {c['agp']} | Kotlin {c['kotlin']} | KSP {c['ksp']} | {c['layout']} {c['extra']} "
      f"| mac: {mac}, task {c['mac_ksp_task']} | ci: {ci} ({total} files), task {task}, rc {rc[1] if rc else '?'} | {same} |")
